#!/bin/bash
# Mac test of where our rows go in Settings' main list (common/MainListRows.h, test-mainlistrows.m; 1.7.9), then the wiring as built.
set -e
cd "$(dirname "$0")"
W=$(mktemp -d); trap 'rm -rf "$W"' EXIT
clang -O2 -fobjc-arc -Wall -Wno-unused-function -framework Foundation -o "$W/tml" test-mainlistrows.m
"$W/tml"
M=../macsettings/MacSettings.x; G=../macsettings/SidebarGroups.x; GH=../common/SidebarGroups.h; D=../dock/dockmagnificationsettings/DockSettingsRow.x
S=../statusbar/macstatusbarsettings/StatusBarSettingsRow.x; P=../macsettings/PointerSettings.x; K=../macsettings/KeyboardSettings.x; H=../common/MainListRows.h
fails=0
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fails=1; fi; }
fn() { awk -v s="$1" 'index($0, s) == 1 {f=1} f {print} f && /^}/ {exit}' "$2"; }
check "the reader never touches the row Settings fills in (the list's -_appleAccountSpecifier, its type checked), nor its cell type" \
  "fn 'static inline NSArray *MSBDMLIdentifiers(id list, NSArray *specs) {' $H | grep -q 'id i = sp != filled && \[sp respondsToSelector:identSel\]' && fn 'static inline id MSBDMLFilledRow(id list) {' $H | grep -q '_appleAccountSpecifier' && fn 'static inline id MSBDMLFilledRow(id list) {' $H | grep -q \"t\[0\] != '@' || method_getNumberOfArguments(m) != 2\" && fn 'static inline NSArray<NSNumber \*> \*MSBDMLCellTypes(id list, NSArray \*specs) {' $H | grep -q 'sp != filled && \[sp respondsToSelector:ct\]'"
check "the list as it is now: the controller's own _specifiers, never asked for (-specifiers)" \
  "fn 'static inline NSArray *MSBDMLLive(id list) {' $H | grep -q 'class_getInstanceVariable(object_getClass(list), \"_specifiers\")' && ! fn 'static inline NSArray *MSBDMLLive(id list) {' $H | grep -q '@selector(specifiers)'"
check "MacSettings: no list kept from a hand-out; the Accessibility group index from the live list, only for the Status Bar and Dock rows" \
  "! grep -q 'kSpecsKey' $M && fn 'static NSInteger AdjustedIndex(id controller, NSArray *insertedSpecs, NSInteger index) {' $M | grep -q 'if (!MSBDMLGoesBeforeAccessibilityGroup(MSBDMLIdentifiers(controller, insertedSpecs))) return index;' && fn 'static NSInteger AdjustedIndex(id controller, NSArray *insertedSpecs, NSInteger index) {' $M | grep -q 'MSBDMLAccessibilityGroupIndex(MSBDMLIdentifiers(controller, MSBDMLLive(controller)), index, kAccessibilityGroupID)'"
check "  ... the hand-out reads each row once (Bluetooth, Accessibility, our rows, the banners), the VPN row and the SSH row's refresh from the live list" \
  "fn '- (NSMutableArray *)specifiers {' $M | grep -q 'NSArray \*ids = MSBDMLIdentifiers(self, specs);' && fn '- (NSMutableArray *)specifiers {' $M | grep -q 'MSBDMLIndexOf(ids, @\"BLUETOOTH\", YES), accessibility = MSBDMLIndexOf(ids, @\"ACCESSIBILITY\", YES)' && ! fn '- (NSMutableArray *)specifiers {' $M | grep -qE 'for \(id s(p)? in specs\) if \(\[\[s(p)? identifier\]' && grep -q 'NSInteger ssh = MSBDMLIndexOf(MSBDMLIdentifiers(self, MSBDMLLive(self)), kSwitchID, NO);' $M && fn 'static void DMRefreshSSHRow(void) {' $M | grep -q 'MSBDMLRowFor(vc, MSBDMLLive(vc), kSwitchID, NO)'"
check "  ... no walk of the main list asks Apple's -specifierForID: (it reads every row) or reads a row's identifier directly" \
  "! fn 'static void MSResyncSidebar(id controller) {' $M | grep -q 'specifierForID' && ! fn 'static void DMRefreshSSHRow(void) {' $M | grep -q 'specifierForID' && [ \$(grep -c 'identifier\]' $M) -eq 0 ] && ! grep -q 'static BOOL IsFollowUp(id spec)' $M"
check "SidebarGroups: the plan and every walk of the sidebar through the reader (Apple's -specifierForID: not asked in the remove hook)" \
  "grep -q 'for (id i in MSBDMLIdentifiers(list, before))' $GH && ! grep -q 'identSel' $GH && fn 'static void SGApply(id list) {' $G | grep -q 'ids = MSBDMLIdentifiers(list, specs);' && ! fn 'static void SGApply(id list) {' $G | grep -q 'SGIdent(sp)' && fn 'static NSString *SGAfterID(id list, NSString *ident) {' $G | grep -q 'MSBDMLIdentifiers(list, SGSpecs(list))' && fn 'static BOOL SGGrouped(int g) {' $G | grep -q 'MSBDMLIdentifiers(root, SGSpecs(root))' && grep -q 'BOOL inList = MSBDMLIndexOf(MSBDMLIdentifiers(self, MSBDMLLive(self)), ident, NO) != NSNotFound;' $G"
check "the Status Bar and Dock rows: one reading of the list, the shared places (no copies of them left), the top fallback by cell types" \
  "( for f in $D $S; do fn 'static void InsertRow(PSListController *list) {' \$f | grep -q 'NSArray \*ids = MSBDMLIdentifiers(list, specs);' || exit 1; fn 'static void InsertRow(PSListController *list) {' \$f | grep -q 'anchor = MSBDMLTop(MSBDMLCellTypes(list, specs));' || exit 1; ! grep -qE 'static NSInteger (AnchorIndex|TopIndex)' \$f || exit 1; done ) && grep -q 'MSBDMLAnchor(ids, nil, windows ? kWindowsRowID : desktop ? kDesktopRowID : kStatusBarRowID)' $D && grep -q 'MSBDMLAnchor(ids, kDockRowID, nil)' $S"
check "  ... PreferenceLoader's listing hidden without reading the row Settings fills in; refreshes, lookups and Settings' page opening through the reader" \
  "( for f in $D $S; do grep -q 'if (\[ident isEqualToString:kRowID\] || !MSBDMLReadable(list, sp)) continue;' \$f || exit 1; fn 'static void RefreshRowValue(void) {' \$f | grep -q 'MSBDMLIndexOf(MSBDMLIdentifiers(l, \[l specifiers\]), gRowID, NO)' || exit 1; done ) && grep -q 'MSBDMLRowFor(list, \[list specifiers\], @\"HOME_SCREEN_DOCK\", NO)' $D && fn '__attribute__((visibility(\"default\"))) id MSBDMainListRow(NSString *ident) {' $S | grep -q 'MSBDMLRowFor(l, \[l specifiers\], ident, NO)' && fn 'static void OpenPage(int attempt, uint32_t target) {' $S | grep -q 'MSBDMLRowFor(list, \[list specifiers\], PageRowID(target), NO)' && fn 'static void InsertDesktopRow(PSListController *list) {' $S | grep -q 'MSBDMLIdentifiers(list, \[list specifiers\])' && fn 'static void InsertWindowsRow(PSListController *list) {' $S | grep -q 'MSBDMLIdentifiers(list, \[list specifiers\])'"
check "the Pointer and Keyboard rows' sidebar checks through the reader" \
  "[ \$(grep -c 'MSBDMLIdentifiers(sidebar, \[sidebar specifiers\])' $P) -eq 1 ] && [ \$(grep -c 'MSBDMLIdentifiers(l, \[l specifiers\])' $P) -eq 2 ] && [ \$(grep -c 'MSBDMLIdentifiers(sidebar, \[sidebar specifiers\])' $K) -eq 1 ] && [ \$(grep -c 'MSBDMLIdentifiers(l, \[l specifiers\])' $K) -eq 1 ] && ! grep -qE 'identifier\] isEqualToString:k(Pointer|Keyboard)RowID' $P $K"
[ $fails = 0 ] && echo "test-mainlistrows: wiring checks pass" || { echo "test-mainlistrows: wiring checks FAILED"; exit 1; }
